				constructor(props) {
					super(props);
					this.state = {
						show: false,
						count: null
					};
				}

				componentDidMount() {
					// eslint-disable-next-line
					this.setState({ show: true });
				}

				componentDidUpdate() {}

				render() {
					if (this.state.show) {
						return (
							<Child
								setValue={i =>
									this.setState({ count: i }, () => {
										invocation = this.state;
									})
								}
							/>
						);
					}
					return null;
				}
			}

			render(<App />, scratch);

			rerender();
			expect(invocation.count).to.equal(10);
		});
